SourceCode.Declaration:
/// <summary>
/// Controller class for CSD transfer orders creation.
/// </summary>
class METCreateCSDTransferOrderController extends SysOperationServiceController
{

}

Method.Source:
/// <summary>
/// Constuct new controller object.
/// </summary>
/// <param name = "_csdSalesOrderList">CSD sales order list.</param>
///  <param name = "_exectionMode">Execution mode.</param>
/// <returns>New controller object.</returns>
public static SysOperationController construct(container _csdSalesOrderList, SysOperationExecutionMode _exectionMode = SysOperationExecutionMode::Synchronous)
{
    METCreateCSDTransferOrderController controller = new METCreateCSDTransferOrderController();

    controller.initContract(_csdSalesOrderList);
    controller.parmLoadFromSysLastValue(false); 
    controller.parmShowDialog(false);
    controller.parmExecutionMode(_exectionMode);

    return controller;
}

/// <summary>
/// Initializes data contract.
/// </summary>
/// <param name = "_csdSalesOrderList">CSD sales order list.</param>
public void initContract(container _csdSalesOrderList)
{
    METCreateCSDTransferOrderContract contract;
    SalesTable                        salesTable;
    SalesId                           salesId;

    contract = this.getDataContractObject() as METCreateCSDTransferOrderContract;
    salesId  = conPeek(_csdSalesOrderList, 1);

    select firstonly InventLocationId from salesTable
        where salesTable.SalesId == salesId;

    contract.parmCSDSalesOrderList(_csdSalesOrderList);
    contract.parmCSDWarehouse(salesTable.InventLocationId);
}

/// <summary>
/// New object
/// </summary>
protected void new()
{
    super(classstr(METCreateCSDTransferOrderService),
          methodstr(METCreateCSDTransferOrderService, process),
           SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Starts the batch job operation.
/// </summary>+
/// <param name = "args">
/// <c>Args</c>.
/// </param>
public static void main(Args args)
{
    METCreateCSDTransferOrderController controller;

    controller = new METCreateCSDTransferOrderController();
    controller.startOperation();
}

/// <summary>
/// Description
/// </summary>
/// <returns>Default caption.</returns>
public ClassDescription defaultCaption()
{
    return "@MET:CreateCSDTransferOrder";
}
